public int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        int max = 0;
        for (Integer num : set) {
            int x = num;
            if (set.contains(x - 1)) {
                continue;
            }
            while (set.contains(x + 1)) {
                x++;
            }
            max = Math.max(max, x - num + 1);
        }
        return max;
    }

